<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0"/>
  <title>Tone Generator</title>
  <style>
    body {
      background: #1e2d45;
      color: white;
      font-family: sans-serif;
      text-align: center;
      padding-top: 40px;
    }
    .knob {
      width: 256px;
      height: 256px;
      background: url('knob.png') no-repeat center;
      background-size: contain;
      margin: 0 auto;
      transform: rotate(0deg);
      transition: transform 0.1s linear;
    }
    input[type=range], input[type=number] {
      margin: 10px;
    }
    button, label {
      margin: 10px;
      font-size: 1em;
      padding: 10px 20px;
      background-color: #4c5c74;
      color: white;
      border: none;
      border-radius: 10px;
    }
    .mode-controls {
      margin-top: 20px;
    }
  </style>
</head>
<body>
  <h1>Tone Generator</h1>
  <div class="knob" id="knob"></div>
  <div>
    Frequency: <span id="freqDisplay">440</span> Hz
  </div>

  <div class="mode-controls">
    <label>
      <input type="radio" name="mode" value="fixed" checked> Fixed
    </label>
    <label>
      <input type="radio" name="mode" value="sweep"> Sweep
    </label>
  </div>

  <div id="sweepControls" style="display:none;">
    Start: <input type="number" id="startFreq" value="200" min="20" max="20000">
    End: <input type="number" id="endFreq" value="1000" min="20" max="20000">
    Duration (s): <input type="number" id="duration" value="5" min="1" max="60">
    <label><input type="checkbox" id="expSweep"> Exponential</label>
  </div>

  <button id="toggleSound">Start</button>

  <script>
    let audioCtx = new (window.AudioContext || window.webkitAudioContext)();
    let oscillator;
    let isPlaying = false;
    let currentFrequency = 440;
    let mode = "fixed";

    const knob = document.getElementById("knob");
    const freqDisplay = document.getElementById("freqDisplay");
    const toggleSound = document.getElementById("toggleSound");

    let angle = 0;

    knob.addEventListener("wheel", function(e) {
      e.preventDefault();
      angle += e.deltaY < 0 ? 5 : -5;
      angle = Math.max(-135, Math.min(135, angle));
      knob.style.transform = `rotate(${angle}deg)`;
      currentFrequency = Math.floor(20 + ((angle + 135) / 270) * (20000 - 20));
      freqDisplay.textContent = currentFrequency;
      if (isPlaying && mode === "fixed") {
        oscillator.frequency.setValueAtTime(currentFrequency, audioCtx.currentTime);
      }
    });

    document.getElementsByName("mode").forEach(el => {
      el.addEventListener("change", () => {
        mode = document.querySelector('input[name="mode"]:checked').value;
        document.getElementById("sweepControls").style.display = mode === "sweep" ? "block" : "none";
      });
    });

    toggleSound.addEventListener("click", () => {
      if (!isPlaying) {
        oscillator = audioCtx.createOscillator();
        oscillator.type = "sine";
        oscillator.connect(audioCtx.destination);

        if (mode === "fixed") {
          oscillator.frequency.setValueAtTime(currentFrequency, audioCtx.currentTime);
          oscillator.start();
        } else {
          let start = parseFloat(document.getElementById("startFreq").value);
          let end = parseFloat(document.getElementById("endFreq").value);
          let dur = parseFloat(document.getElementById("duration").value);
          let exp = document.getElementById("expSweep").checked;

          oscillator.frequency.setValueAtTime(start, audioCtx.currentTime);
          if (exp) {
            oscillator.frequency.exponentialRampToValueAtTime(end, audioCtx.currentTime + dur);
          } else {
            oscillator.frequency.linearRampToValueAtTime(end, audioCtx.currentTime + dur);
          }

          oscillator.start();
          oscillator.stop(audioCtx.currentTime + dur);
          setTimeout(() => {
            isPlaying = false;
            toggleSound.textContent = "Start";
          }, dur * 1000);
        }

        isPlaying = true;
        toggleSound.textContent = "Stop";
      } else {
        oscillator.stop();
        isPlaying = false;
        toggleSound.textContent = "Start";
      }
    });
  </script>
</body>
</html>
```

