Here's the **updated and corrected** version of the `startStopBtn` click handler, with:

- Removal of duplicate `const mode = ...`
- Proper error handling
- User feedback via `alert()` popups for failure cases

```javascript
document.getElementById("startStopBtn").addEventListener("click", () => {
  try {
    if (isPlaying) {
      if (oscillator) {
        try {
          oscillator.stop();
          oscillator.disconnect();
        } catch (err) {
          alert("Error while stopping oscillator: " + err.message);
        }
        oscillator = null;
      }
      if (window.rangeOscillators) {
        try {
          window.rangeOscillators.forEach(osc => {
            osc.stop();
            osc.disconnect();
          });
        } catch (err) {
          alert("Error stopping range oscillators: " + err.message);
        }
        window.rangeOscillators = [];
      }
      isPlaying = false;
      document.getElementById("startStopBtn").textContent = "Start";
      return;
    }

    const mode = document.querySelector('input[name="mode"]:checked').value;
    oscillator = audioCtx.createOscillator();
    oscillator.type = "sine";
    oscillator.connect(gainNode);

    if (mode === "sweep") {
      const startFreq = parseFloat(document.getElementById("startFreq").value);
      const endFreq = parseFloat(document.getElementById("endFreq").value);
      const duration = parseFloat(document.getElementById("duration").value);
      const useExp = document.getElementById("expSweep").checked;

      oscillator.frequency.setValueAtTime(startFreq, audioCtx.currentTime);
      if (useExp) {
        oscillator.frequency.exponentialRampToValueAtTime(endFreq, audioCtx.currentTime + duration);
      } else {
        oscillator.frequency.linearRampToValueAtTime(endFreq, audioCtx.currentTime + duration);
      }

      oscillator.start();
      oscillator.stop(audioCtx.currentTime + duration);
      setTimeout(() => {
        isPlaying = false;
        document.getElementById("startStopBtn").textContent = "Start";
      }, duration * 1000);
    } else {
      const freq = parseFloat(document.getElementById("freqInput").value);
      oscillator.frequency.setValueAtTime(freq, audioCtx.currentTime);
      oscillator.start();
    }

    isPlaying = true;
    document.getElementById("startStopBtn").textContent = "Stop";
  } catch (err) {
    alert("Failed to start/stop tone generator.\nReason: " + err.message);
    console.error("Tone Generator Error:", err);
    isPlaying = false;
    document.getElementById("startStopBtn").textContent = "Start";
  }
});
```

This version provides:

- Specific alerts if stopping an oscillator fails
- A catch-all alert if anything else goes wrong (e.g. missing context, invalid input)
- Restoration of the button label to `"Start"` on any error

