  <label for="startFreq">Start:</label>
  <input id="startFreq" max="20000" min="20" type="number" value="500"/>
  <label for="endFreq">End:</label>
  <input id="endFreq" max="20000" min="20" type="number" value="2000"/>
  <label for="duration">Duration (s):</label>
  <input id="duration" maxlength="4" size="4" type="text" value="5"/>
  <label><input id="expSweep" type="checkbox"/> Exponential</label>
</div>
<button id="startStopBtn">Start</button>

<script>
// === Modular Tone Generator ===

let audioContext = null;
let oscillatorNode = null;
let gainControlNode = null;
let isOscillatorPlaying = false;

const frequencyInput = document.getElementById("frequency");
const frequencyDisplay = document.getElementById("freqDisplay");
const volumeSlider = document.getElementById("volumeControl");
const playToggleButton = document.getElementById("startStopBtn");

frequencyInput.addEventListener("input", handleFrequencyChange);
volumeSlider.addEventListener("input", handleVolumeChange);
document.getElementsByName("mode").forEach(el => el.addEventListener("change", updateSweepControlsVisibility));
playToggleButton.addEventListener("click", togglePlayback);

function handleFrequencyChange() {
  const freq = frequencyInput.value;
  frequencyDisplay.textContent = `Current Frequency: ${freq} Hz`;
  if (oscillatorNode && isOscillatorPlaying && getCurrentMode() === "fixed") {
    oscillatorNode.frequency.setValueAtTime(parseFloat(freq), audioContext.currentTime);
  }
}

function handleVolumeChange() {
  if (gainControlNode) {
    gainControlNode.gain.setValueAtTime(volumeSlider.value / 100, audioContext.currentTime);
  }
}

function getCurrentMode() {
  return document.querySelector('input[name="mode"]:checked').value;
}

function updateSweepControlsVisibility() {
  const sweepControls = document.getElementById("sweepControls");
  sweepControls.style.display = (getCurrentMode() === "sweep") ? "block" : "none";
}

function togglePlayback() {
  if (!audioContext) {
    audioContext = new (window.AudioContext || window.webkitAudioContext)();
  }

  if (isOscillatorPlaying) {
    stopOscillator();
  } else {
    startOscillator();
  }
}

function startOscillator() {
  try {
    oscillatorNode = audioContext.createOscillator();
    gainControlNode = audioContext.createGain();

    oscillatorNode.type = "sine";
    gainControlNode.gain.setValueAtTime(volumeSlider.value / 100, audioContext.currentTime);

    oscillatorNode.connect(gainControlNode);
    gainControlNode.connect(audioContext.destination);

    const mode = getCurrentMode();

    if (mode === "sweep") {
      const start = parseFloat(document.getElementById("startFreq").value);
      const end = parseFloat(document.getElementById("endFreq").value);
      const duration = parseFloat(document.getElementById("duration").value);
      const exponential = document.getElementById("expSweep").checked;

      oscillatorNode.frequency.setValueAtTime(start, audioContext.currentTime);
      if (exponential) {
        oscillatorNode.frequency.exponentialRampToValueAtTime(end, audioContext.currentTime + duration);
      } else {
        oscillatorNode.frequency.linearRampToValueAtTime(end, audioContext.currentTime + duration);
      }

      oscillatorNode.start();
      oscillatorNode.stop(audioContext.currentTime + duration);

      setTimeout(() => {
        isOscillatorPlaying = false;
        playToggleButton.textContent = "Start";
      }, duration * 1000);

    } else {
      const fixedFreq = parseFloat(frequencyInput.value);
      oscillatorNode.frequency.setValueAtTime(fixedFreq, audioContext.currentTime);
      oscillatorNode.start();
    }

    isOscillatorPlaying = true;
    playToggleButton.textContent = "Stop";
  } catch (err) {
    alert("Error: " + err.message);
    console.error(err);
  }
}

function stopOscillator() {
  if (oscillatorNode) oscillatorNode.stop();
  if (oscillatorNode) oscillatorNode.disconnect();
  if (gainControlNode) gainControlNode.disconnect();

  oscillatorNode = null;
  gainControlNode = null;
  isOscillatorPlaying = false;
  playToggleButton.textContent = "Start";
}
</script>

</body>
</html>
